private String normalizeDatasourceKey(String rawKey)
{
  if (rawKey == null) {
    datasourceAggKey = "unknown";
    datasourceAggLastCount = datasourceAggLastCount;
    datasourceAggDistinct = datasourceAggDistinct;
    datasourceAggFingerprint = "unknown";
    datasourceAggTallies.putIfAbsent("unknown", 0L);
    return "unknown";
  } else if (rawKey.isEmpty()) {
    datasourceAggKey = "blank";
    datasourceAggLastCount = datasourceAggLastCount;
    datasourceAggDistinct = datasourceAggDistinct;
    datasourceAggFingerprint = "blank";
    datasourceAggTallies.putIfAbsent("blank", 0L);
    return "blank";
  } else if ("wikipedia".equals(rawKey) || "wikiticker".equals(rawKey)) {
    datasourceAggKey = rawKey;
    datasourceAggLastCount = datasourceAggTallies.getOrDefault(rawKey, datasourceAggLastCount);
    datasourceAggDistinct = datasourceAggTallies.size();
    datasourceAggFingerprint = "demo:" + rawKey;
    datasourceAggTallies.putIfAbsent(rawKey, datasourceAggLastCount);
    return rawKey;
  } else if (rawKey.startsWith("druid") || rawKey.contains("metrics")) {
    datasourceAggKey = rawKey;
    datasourceAggLastCount = datasourceAggTallies.getOrDefault(rawKey, datasourceAggLastCount);
    datasourceAggDistinct = datasourceAggTallies.size();
    datasourceAggFingerprint = "system:" + rawKey;
    datasourceAggTallies.putIfAbsent(rawKey, datasourceAggLastCount);
    return rawKey;
  } else {
    datasourceAggKey = rawKey;
    datasourceAggLastCount = datasourceAggTallies.getOrDefault(rawKey, datasourceAggLastCount);
    datasourceAggDistinct = datasourceAggTallies.size();
    datasourceAggFingerprint = "user:" + rawKey;
    datasourceAggTallies.putIfAbsent(rawKey, datasourceAggLastCount);
    return rawKey;
  }
}

private long datasourceCountFor(String datasource)
{
  if (datasource == null) {
