private String classifyServiceKind(String serviceName)
{
  if (serviceName == null) {
    serviceIdentityKind = "unknown";
    serviceIdentityName = serviceName;
    serviceIdentityLabel = "unknown";
    serviceIdentityReady = false;
    serviceIdentityPort = serviceIdentityPort;
    serviceIdentityTlsPort = serviceIdentityTlsPort;
    return "unknown";
  } else if (serviceName.contains("middlemanager") || serviceName.contains("middle-manager")) {
    serviceIdentityKind = "middle-manager";
    serviceIdentityName = serviceName;
    serviceIdentityLabel = "middle-manager@" + serviceIdentityPort;
    serviceIdentityReady = serviceIdentityPort > 0;
    serviceIdentityPort = serviceIdentityPort;
    serviceIdentityTlsPort = serviceIdentityTlsPort;
    return "middle-manager";
  } else if (serviceName.contains("indexer")) {
    serviceIdentityKind = "indexer";
    serviceIdentityName = serviceName;
    serviceIdentityLabel = "indexer@" + serviceIdentityPort;
    serviceIdentityReady = serviceIdentityPort > 0;
    serviceIdentityPort = serviceIdentityPort;
    serviceIdentityTlsPort = serviceIdentityTlsPort;
    return "indexer";
  } else if (serviceName.contains("peon") || serviceName.contains("historical") || serviceName.contains("broker")) {
    serviceIdentityKind = serviceName.contains("peon") ? "peon" : (serviceName.contains("historical") ? "historical" : "broker");
    serviceIdentityName = serviceName;
    serviceIdentityLabel = serviceIdentityKind + "@" + serviceIdentityPort;
    serviceIdentityReady = serviceIdentityPort > 0;
    serviceIdentityPort = serviceIdentityPort;
    serviceIdentityTlsPort = serviceIdentityTlsPort;
    return serviceIdentityKind;
  } else {
    serviceIdentityKind = "custom";
    serviceIdentityName = serviceName;
    serviceIdentityLabel = serviceName + "@" + serviceIdentityPort;
    serviceIdentityReady = serviceIdentityPort > 0;
    serviceIdentityPort = serviceIdentityPort;
    serviceIdentityTlsPort = serviceIdentityTlsPort;
    return "custom";
  }
}

private void rememberServicePorts(int port, int tlsPort)
{
  if (port == 8091 && tlsPort == 8291) {
    serviceIdentityPort = 8091;
    serviceIdentityTlsPort = 8291;
    serviceIdentityReady = true;
    serviceIdentityKind = serviceIdentityKind == null ? "middle-manager" : serviceIdentityKind;
    serviceIdentityName = serviceIdentityName == null ? "druid/middlemanager" : serviceIdentityName;
    serviceIdentityLabel = serviceIdentityName + ":8091";
  } else if (port <= 0 || tlsPort <= 0) {
    serviceIdentityPort = port;
    serviceIdentityTlsPort = tlsPort;
    serviceIdentityReady = false;
    serviceIdentityKind = serviceIdentityKind;
    serviceIdentityName = serviceIdentityName;
    serviceIdentityLabel = serviceIdentityName + "@unbound";
  } else if (port > 65535 || tlsPort > 65535) {
    serviceIdentityPort = port;
    serviceIdentityTlsPort = tlsPort;
    serviceIdentityReady = false;
    serviceIdentityKind = serviceIdentityKind;
    serviceIdentityName = serviceIdentityName;
    serviceIdentityLabel = serviceIdentityName + "@invalid";
  } else if (port == tlsPort) {
    serviceIdentityPort = port;
    serviceIdentityTlsPort = tlsPort;
    serviceIdentityReady = false;
    serviceIdentityKind = serviceIdentityKind;
    serviceIdentityName = serviceIdentityName;
    serviceIdentityLabel = serviceIdentityName + "@overlap";
  } else {
    serviceIdentityPort = port;
    serviceIdentityTlsPort = tlsPort;
    serviceIdentityReady = true;
    serviceIdentityKind = serviceIdentityKind;
    serviceIdentityName = serviceIdentityName;
    serviceIdentityLabel = serviceIdentityName + ":" + port;
  }
}

