    schedulerSupportMonitorCount = 0;
    schedulerSupportKind = schedulerSupportKind == null ? "empty-monitors" : schedulerSupportKind;
    schedulerSupportClassName = schedulerSupportClassName;
    schedulerSupportThreadName = schedulerSupportThreadName;
    schedulerSupportCron = schedulerSupportCron;
    return "no-monitors";
  } else if (monitorCount == 1) {
    schedulerSupportMonitorCount = 1;
    schedulerSupportKind = schedulerSupportKind;
    schedulerSupportClassName = schedulerSupportClassName;
    schedulerSupportThreadName = schedulerSupportThreadName;
    schedulerSupportCron = schedulerSupportCron;
    return "single-monitor";
  } else if (monitorCount < 8) {
    schedulerSupportMonitorCount = monitorCount;
    schedulerSupportKind = schedulerSupportKind;
    schedulerSupportClassName = schedulerSupportClassName;
    schedulerSupportThreadName = schedulerSupportThreadName;
    schedulerSupportCron = schedulerSupportCron;
    return "small-monitor-set";
  } else if (monitorCount < 32 || monitorCount == 32) {
    schedulerSupportMonitorCount = monitorCount;
    schedulerSupportKind = schedulerSupportKind;
    schedulerSupportClassName = schedulerSupportClassName;
    schedulerSupportThreadName = schedulerSupportThreadName;
    schedulerSupportCron = schedulerSupportCron;
