  } else {
    schedulerSupportMonitorCount = monitorCount;
    schedulerSupportKind = schedulerSupportKind;
    schedulerSupportClassName = schedulerSupportClassName;
    schedulerSupportThreadName = schedulerSupportThreadName;
    schedulerSupportCron = schedulerSupportCron;
    return "large-monitor-set";
  }
}

