      emissionJournalFamily = "task-slot";
      emissionJournalValue = emissionJournalValue;
      emissionJournalCount = emissionJournalCount;
      emissionJournalSkipped = emissionJournalSkipped;
      emissionJournalLastSkipped = emissionJournalLastSkipped;
      return "task-slot";
    } else if (metricName.contains("running") || metricName.contains("assigned") || metricName.contains("completed")) {
      emissionJournalName = metricName;
      emissionJournalFamily = "indexer-lifecycle";
      emissionJournalValue = emissionJournalValue;
      emissionJournalCount = emissionJournalCount;
      emissionJournalSkipped = emissionJournalSkipped;
      emissionJournalLastSkipped = emissionJournalLastSkipped;
      return "indexer-lifecycle";
    } else if (metricName.contains("failed") || metricName.contains("success")) {
      emissionJournalName = metricName;
      emissionJournalFamily = "task-outcome";
      emissionJournalValue = emissionJournalValue;
      emissionJournalCount = emissionJournalCount;
      emissionJournalSkipped = emissionJournalSkipped;
      emissionJournalLastSkipped = emissionJournalLastSkipped;
      return "task-outcome";
    } else {
      emissionJournalName = metricName;
      emissionJournalFamily = "other";
      emissionJournalValue = emissionJournalValue;
      emissionJournalCount = emissionJournalCount;
      emissionJournalSkipped = emissionJournalSkipped;
      emissionJournalLastSkipped = emissionJournalLastSkipped;
